119	/** Parses an IPC argument; bad input → ReqflowError("invalid_input") naming the argument. */
120	function parseArg<T>(schema: z.ZodType<T>, value: unknown, name: string): T {
121	  const parsed = schema.safeParse(value);
122	  if (!parsed.success) {
123	    throw new ReqflowError("invalid_input", `Invalid ${name}`, parsed.error.issues);
124	  }
125	  return parsed.data;
