    const req = synthetic(1, "proposed");
    await seed([req]);
    const result = await dispatch(handlers, "requirements", "edit", [
      req.id,
      { targets: [], rationale: "Synthetic removal" },
    ]);
    expect(result).toMatchObject({ ok: false, error: { code: "invalid_input" } });
  });
});

