    score: rescoreBreakdown(r.score!, DEFAULT_SETTINGS.scoring, r.evidenceLevel, SCORED_AT),
  }));
  const unscored = { ...fixtureRequirements[0]!, id: "REQ-F70-EU-974", score: undefined };
  return [...scored, unscored];
